DROP SCHEMA IF EXISTS trucker CASCADE;
CREATE SCHEMA trucker;

CREATE TABLE trucker.store_sales_pg (
  id                  text    PRIMARY KEY,
  quantity            int,
  net_paid            float8,
  net_profit          float8,
  net_paid_inc_tax    float8,
  ext_discount_amt    float8,
  sale_year           int,
  sale_month          int,
  store_name          text,
  store_state         text,
  customer_last_name  text,
  item_category       text,
  item_brand          text,
  deleted             boolean NOT NULL DEFAULT false
);

CREATE TABLE trucker.store_pg (
  id                  text    PRIMARY KEY,
  store_id            text,
  rec_start_date      date,
  rec_end_date        date,
  closed_date_sk      int,
  store_name          text,
  number_employees    int,
  floor_space         int,
  hours               text,
  manager             text,
  market_id           int,
  geography_class     text,
  market_desc         text,
  market_manager      text,
  division_id         int,
  division_name       text,
  company_id          int,
  company_name        text,
  street_number       text,
  street_name         text,
  street_type         text,
  suite_number        text,
  city                text,
  county              text,
  state               text,
  zip                 text,
  country             text,
  gmt_offset          float8,
  tax_precentage      float8,
  deleted             boolean NOT NULL DEFAULT false
);

CREATE TABLE trucker.date_dim_pg (
  id                  text    PRIMARY KEY,
  date_id             text,
  d_date              date,
  month_seq           int,
  week_seq            int,
  quarter_seq         int,
  d_year              int,
  dow                 int,
  moy                 int,
  dom                 int,
  qoy                 int,
  fy_year             int,
  fy_quarter_seq      int,
  fy_week_seq         int,
  day_name            text,
  quarter_name        text,
  holiday             text,
  weekend             text,
  following_holiday   text,
  first_dom           int,
  last_dom            int,
  same_day_ly         int,
  same_day_lq         int,
  current_day         text,
  current_week        text,
  current_month       text,
  current_quarter     text,
  current_year        text,
  deleted             boolean NOT NULL DEFAULT false
);

CREATE TABLE trucker.customer_pg (
  id                    text    PRIMARY KEY,
  customer_id           text,
  current_cdemo_sk      int,
  current_hdemo_sk      int,
  current_addr_sk       int,
  first_shipto_date_sk  int,
  first_sales_date_sk   int,
  salutation            text,
  first_name            text,
  last_name             text,
  preferred_cust_flag   text,
  birth_day             int,
  birth_month           int,
  birth_year            int,
  birth_country         text,
  login                 text,
  email_address         text,
  last_review_date_sk   int,
  deleted               boolean NOT NULL DEFAULT false
);

CREATE TABLE trucker.item_pg (
  id              text    PRIMARY KEY,
  item_id         text,
  rec_start_date  date,
  rec_end_date    date,
  item_desc       text,
  current_price   float8,
  wholesale_cost  float8,
  brand_id        int,
  brand           text,
  class_id        int,
  i_class         text,
  category_id     int,
  category        text,
  manufact_id     int,
  manufact        text,
  i_size          text,
  formulation     text,
  color           text,
  units           text,
  container       text,
  manager_id      int,
  product_name    text,
  deleted         boolean NOT NULL DEFAULT false
);
